## DOM Access with useRef

## Basic Pattern

```tsx
import { useRef, useEffect } from 'react';

function SearchInput() {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus(); // auto-focus on mount
  }, []);

  return <input ref={inputRef} type="search" />;
}
```

## Common Use Cases

```tsx
// Scroll to element
const bottomRef = useRef<HTMLDivElement>(null);
bottomRef.current?.scrollIntoView({ behavior: 'smooth' });

// Read DOM measurements
const boxRef = useRef<HTMLDivElement>(null);
const width = boxRef.current?.getBoundingClientRect().width;

// Media control
const videoRef = useRef<HTMLVideoElement>(null);
videoRef.current?.play();
```

## Callback Refs

For dynamic elements or when you need to react to the ref being set:

```tsx
function MeasuredBox() {
  const [height, setHeight] = useState(0);

  const measuredRef = useCallback((node: HTMLDivElement | null) => {
    if (node) setHeight(node.getBoundingClientRect().height);
  }, []);

  return <div ref={measuredRef}>Content</div>;
}
```

## Forwarding Refs to Custom Components

```tsx
const FancyInput = forwardRef<HTMLInputElement, Props>((props, ref) => (
  <input ref={ref} {...props} />
));

// Parent
const ref = useRef<HTMLInputElement>(null);
<FancyInput ref={ref} />
```

